    }
    // hostname: try to resolve
    // Use ToSocketAddrs with port 0
    let addrs = (host, 0).to_socket_addrs();
    match addrs {
        Ok(iter) => {
            let ips: Vec<IpAddr> = iter.map(|sa| sa.ip()).collect();
            if ips.is_empty() {
