                    }
                } else {
                    // Should be Resolving error? But we already have ips from successful resolution, so not.
                    return Ok(ips);
                }
            }
            if four {
                let v4: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv4()).cloned().collect();
                if v4.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv4", original_for_error));
                }
                Ok(v4)
            } else if six {
                let v6: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv6()).cloned().collect();
                if v6.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv6", original_for_error));
                }
                Ok(v6)
            } else {
                Ok(ips)
            }
        }
        Err(e) => {
            // Distinguish between "No address associated" vs other?
            // Original error messages:
            // "Error: Resolving <host>\n\nCaused by:\n    failed to lookup address information: <msg>"
            // The cause message comes from io error. For std, e.to_string() may be "failed to lookup address information: ..."
