    // if secs >=1: format as "X.YZs" ?
    // else if millis >=1: format as "X.Yms" or "Xms"
    // else if micros >=1: "Xµs" or "X.Yµs"
    // else "Xns"

    // We'll try to match observed: "15.5ms" – 15.5 ms has one decimal.
    // "11.1ms" – one decimal.
    // "20ms" – no decimal.
    // "687µs" – no decimal.
    // "100.787ms" – three decimals? Actually earlier capture for cmd mode: "last 100.787m" truncated, but likely "100.787ms".
    // So maybe they format with 3 significant digits? Or they show microseconds for cmd? Let's use debug format: "{:?}" for Duration gives "687µs", "100.787ms"? Actually Duration Debug might give that.

    // For simplicity, we will format using floating milliseconds with minimal trimming.

    let micros = d.as_micros() as f64;
    if d.as_secs() >= 1 {
        // show seconds with ms? Example "2s" was shown for timeout? We saw "last 2s" for timeout case.
        // So if >=1s, show like "2s" or "1.5s"?
        let secs = d.as_secs_f64();
        if secs >= 10.0 {
            format!("{:.0}s", secs)
        } else {
            format!("{:.1}s", secs)
        }
    } else if d.as_millis() >= 1 {
        let ms = d.as_secs_f64() * 1000.0;
        if ms >= 100.0 {
            format!("{:.0}ms", ms)
        } else if ms >= 10.0 {
            format!("{:.1}ms", ms)
        } else {
            format!("{:.1}ms", ms) // maybe more?
        }
    } else if d.as_micros() >= 1 {
        let us = d.as_secs_f64() * 1_000_000.0;
        if us >= 100.0 {
            format!("{:.0}µs", us)
        } else {
            format!("{:.1}µs", us)
        }
    } else {
        format!("{}ns", d.as_nanos())
    }
}

fn main() {
    let cli = build_cli();
    let matches = cli.get_matches();

    let is_cmd = matches.get_flag("cmd");
    let watch_interval_opt: Option<f64> = matches.get_one::<f64>("watch-interval").cloned();
    let buffer: u64 = *matches.get_one::<u64>("buffer").unwrap();
    let four = matches.get_flag("4");
    let six = matches.get_flag("6");
    let interface: Option<String> = matches.get_one::<String>("interface").cloned();
    let simple_graphics = matches.get_flag("simple-graphics");
    let vertical_margin: u64 = *matches.get_one::<u64>("vertical-margin").unwrap();
    let horizontal_margin: u64 = *matches.get_one::<u64>("horizontal-margin").unwrap();
    let clear = matches.get_flag("clear");
    let ping_args: Vec<String> = matches.get_many::<String>("ping-args").map(|v| v.cloned().collect()).unwrap_or_default();
    let hosts_raw: Vec<String> = matches.get_many::<String>("hosts").map(|v| v.cloned().collect()).unwrap_or_default();

    if hosts_raw.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        process::exit(1);
    }

    // Parse colors
    let color_raw: Vec<String> = matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
    // Split raw by comma preserving original
    let mut all_color_pieces: Vec<String> = Vec::new();
    for raw in &color_raw {
        for part in raw.split(',') {
            all_color_pieces.push(part.to_string());
        }
    }

    // Validate colors for needed hosts
    let validate_count = std::cmp::min(all_color_pieces.len(), hosts_raw.len());
    // Helper to check color validity
    let is_valid = |piece: &str| -> bool {
        // hex exact
        if piece.len() == 7 && piece.starts_with('#') && piece[1..].chars().all(|c| c.is_ascii_hexdigit()) {
            return true;
        }
        let trimmed = piece.trim();
        if trimmed.is_empty() {
            return false;
        }
        let lower = trimmed.to_lowercase();
        matches!(lower.as_str(), "black"|"red"|"green"|"yellow"|"blue"|"magenta"|"cyan"|"gray"|"dark-gray"|"light-red"|"light-green"|"light-yellow"|"light-blue"|"light-magenta"|"light-cyan"|"white")
    };

    for i in 0..validate_count {
        let piece = &all_color_pieces[i];
        if !is_valid(piece) {
            eprintln!("Error: Invalid color code: `{}`\n\nCaused by:\n    Failed to parse Colors", piece);
            process::exit(1);
        }
    }

    // For any color pieces beyond validate_count, we ignore invalid? Actually according to earlier logic, extra beyond hosts should be ignored even if invalid. So we already ignore beyond validate_count.
    // But what about invalid before validate_count? We already error.

    // Also need to check any invalid color in all pieces that is before first valid? Our validate_count logic handles leading invalid because if first piece invalid and hosts_len>=1, validate_count includes it and errors.
    // What about case where first piece invalid but hosts_len=0? Already handled hosts empty earlier.

    // Map cloud shorthands and resolve
    let mut hosts_info: Vec<HostInfo> = Vec::new();
    for original in &hosts_raw {
        let mapped = map_cloud(original);
        // For error messages, we need to show mapped host in resolve errors, but original_for_error should be mapped? We saw for aws:eu-west-1, error shows mapped ec2... So use mapped for error.
        // For Could not resolve to IPv4/IPv6, also mapped.
        let resolve_result = resolve_host(&mapped, four, six, &mapped);
        match resolve_result {
            Ok(ips) => {
                // Pick first IP for display? Original shows resolved IP in parentheses, like "127.0.0.1 (127.0.0.1)" or "google.com (192.178.155.139)" – it shows resolved IP.
                // So we need to pick an IP: if -4, pick first v4; if -6, first v6; else first of any? For google.com without flag, it showed IPv4 (192...). So it prefers IPv4 when both exist? That matches earlier: google.com without flag used ping (IPv4) and displayed IPv4. For localhost, it displayed IPv4? Actually localhost with both, without flag it used ping and displayed? We didn't capture resolved IP for localhost.
                // For simplicity, we will pick first IP that matches family preference, else first.
                let display_ip = if four {
                    ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                } else if six {
                    ips.iter().find(|ip| ip.is_ipv6()).cloned().unwrap_or(ips[0])
                } else {
                    // Prefer IPv4? Let's prefer IPv4 if exists, else IPv6.
                    ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                };
                let is_v6_lit = IpAddr::from_str(&mapped).map(|ip| ip.is_ipv6()).unwrap_or(false) || (original.contains(':') && !original.starts_with("aws:") && !original.starts_with("gcp:"));
                // Actually is_ipv6_literal should be based on mapped? For cloud, mapped is hostname, not literal, so false. For original IP literal like ::1, true.
                let is_v6 = if let Ok(ip) = IpAddr::from_str(&mapped) { ip.is_ipv6() } else { original.contains(':') && IpAddr::from_str(original).map(|ip| ip.is_ipv6()).unwrap_or(false) };

                hosts_info.push(HostInfo {
                    original: original.clone(),
                    display: original.clone(),
                    mapped: mapped.clone(),
                    resolved_ip: display_ip.to_string(),
                    is_ipv6_literal: is_v6,
                });
            }
            Err(err_msg) => {
                eprintln!("{}", err_msg);
                process::exit(1);
            }
        }
    }

    // Check ping binary if not in cmd mode
    if !is_cmd {
        if let Err(e) = check_ping_binary() {
            eprintln!("{}", e);
            process::exit(1);
        }
    }

    // Determine watch interval
    let default_interval = if is_cmd { 0.5 } else { 0.2 };
    let interval = watch_interval_opt.unwrap_or(default_interval);
    // Format interval for ping args: format with one decimal as original
    let interval_str = format!("{:.1}", interval);

    // Setup TUI if TTY? Original checks if not TTY, error "No such device or address (os error 6)"
    // We can check if stdout is TTY using crossterm::tty::IsTty
    // For simplicity, try to enable raw mode, if fails, print error and exit 1.
    use crossterm::tty::IsTty;
    if !std::io::stdout().is_tty() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }

    // Now implement TUI loop
    // We'll use ratatui and crossterm

    // For ping mode: spawn ping processes
    // For cmd mode: run commands in loop

    // For simplicity, we will implement a basic TUI that shows headers and a placeholder graph, and updates stats.

    // Setup terminal
    use crossterm::{
        execute,
        terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
        event::{self, Event, KeyCode},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Layout, Constraint, Direction},
        style::{Color, Style},
        widgets::{Block, Borders, Paragraph},
        Terminal,
    };

    if let Err(_) = enable_raw_mode() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let mut stdout = std::io::stdout();
    if let Err(_) = execute!(stdout, EnterAlternateScreen) {
        let _ = disable_raw_mode();
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            eprintln!("Error: No such device or address (os error 6)");
            process::exit(1);
        }
    };

    // Data structures for ping stats
    struct PingData {
        host_info: HostInfo,
        times: VecDeque<(Instant, Option<Duration>)>,
        last: Option<Duration>,
        min: Option<Duration>,
        max: Option<Duration>,
        sum: Duration,
        count: u64,
        timeouts: u64,
        jitter_sum: Duration,
        prev: Option<Duration>,
    }

    impl PingData {
        fn new(host_info: HostInfo) -> Self {
            Self {
                host_info,
                times: VecDeque::new(),
                last: None,
                min: None,
                max: None,
                sum: Duration::from_secs(0),
                count: 0,
                timeouts: 0,
                jitter_sum: Duration::from_secs(0),
                prev: None,
            }
        }

        fn add(&mut self, dur: Option<Duration>) {
            let now = Instant::now();
            self.times.push_back((now, dur));
            // Keep only buffer seconds
            // We'll filter later based on buffer
            if let Some(d) = dur {
                self.last = Some(d);
                self.min = Some(match self.min {
                    Some(m) => if d < m { d } else { m },
                    None => d,
                });
                self.max = Some(match self.max {
                    Some(m) => if d > m { d } else { m },
                    None => d,
                });
                self.sum += d;
                self.count += 1;
                if let Some(prev) = self.prev {
                    let diff = if d > prev { d - prev } else { prev - d };
                    self.jitter_sum += diff;
                }
                self.prev = Some(d);
            } else {
                self.timeouts += 1;
                // For timeout, we still keep prev? Probably not update prev for jitter?
            }
        }

        fn avg(&self) -> Option<Duration> {
            if self.count == 0 { None } else { Some(self.sum / self.count as u32) }
        }

        fn jitter(&self) -> Option<Duration> {
            if self.count <= 1 { None } else { Some(self.jitter_sum / (self.count -1) as u32) }
        }
    }

    // For ping mode, spawn ping processes
    // We need to handle multiple hosts
    use std::sync::mpsc::{self, Receiver};
    use std::thread;

    enum PingEvent {
        Data { host_idx: usize, duration: Option<Duration>, line: String },
        Error { host_idx: usize, error: String },
    }

    let (tx, rx) = mpsc::channel();

    let mut ping_handles = vec![];

    if !is_cmd {
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let mapped = host_info.mapped.clone();
            let interval_str_clone = interval_str.clone();
            let interface_clone = interface.clone();
            let ping_args_clone = ping_args.clone();
            let tx_clone = tx.clone();
            let is_ipv6 = if six {
                true
            } else if four {
                false
            } else {
                host_info.is_ipv6_literal
            };
            // Choose binary: if is_ipv6, try ping6, else ping
            let ping_bin = if is_ipv6 { "ping6" } else { "ping" };
            // Spawn thread to run ping
            let handle = thread::spawn(move || {
                // Build args: -O -i<interval> [-I interface] [ping_args] host
                let mut args: Vec<String> = vec![];
                args.push("-O".to_string());
                args.push(format!("-i{}", interval_str_clone));
                if let Some(ref iface) = interface_clone {
                    args.push("-I".to_string());
                    args.push(iface.clone());
                }
                for pa in ping_args_clone {
                    args.push(pa);
                }
                args.push(mapped.clone());

                // Try to spawn ping_bin, if fails try "ping" as fallback? Original tries ping6 for ipv6, but if ping6 not found, error spawning. So we try ping_bin, if fails, try fallback?
                // For simplicity, try ping_bin, if fails and ping_bin != "ping", try "ping", else error.
                let mut child = match std::process::Command::new(ping_bin)
                    .args(&args)
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::piped())
                    .spawn() {
                        Ok(c) => c,
                        Err(e) => {
                            // If ping_bin is ping6 and fails, try ping?
                            if ping_bin == "ping6" {
                                match std::process::Command::new("ping")
                                    .args(&args)
                                    .stdout(std::process::Stdio::piped())
                                    .stderr(std::process::Stdio::piped())
                                    .spawn() {
                                        Ok(c) => c,
                                        Err(e2) => {
                                            let _ = tx_clone.send(PingEvent::Error { host_idx: idx, error: format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e2, e2.raw_os_error().unwrap_or(2), e2, e2.raw_os_error().unwrap_or(2)) });
                                            return;
                                        }
                                    }
                            } else {
                                let _ = tx_clone.send(PingEvent::Error { host_idx: idx, error: format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e, e.raw_os_error().unwrap_or(2), e, e.raw_os_error().unwrap_or(2)) });
                                return;
                            }
                        }
                    };

                let stdout = child.stdout.take().unwrap();
                let reader = std::io::BufReader::new(stdout);
                use std::io::BufRead;
                let re = Regex::new(r"time=([0-9]+\.?[0-9]*)\s*ms").unwrap();
                let timeout_re = Regex::new(r"no answer yet").unwrap();
                for line in reader.lines() {
                    if let Ok(l) = line {
                        if timeout_re.is_match(&l) {
                            let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: None, line: l });
                        } else if let Some(cap) = re.captures(&l) {
                            if let Some(m) = cap.get(1) {
                                if let Ok(ms) = f64::from_str(m.as_str()) {
                                    let dur = Duration::from_secs_f64(ms / 1000.0);
                                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(dur), line: l });
                                }
                            }
                        }
                    }
                }
            });
            ping_handles.push(handle);
        }
    } else {
        // cmd mode: for each command, spawn thread that runs command in loop with interval
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let cmd_str = host_info.original.clone();
            let tx_clone = tx.clone();
            let interval_clone = interval;
            thread::spawn(move || {
                loop {
                    let start = Instant::now();
                    let result = std::process::Command::new("sh").arg("-c").arg(&cmd_str).output();
                    let elapsed = start.elapsed();
                    // Consider command failure? Original still records time even if fails?
                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(elapsed), line: format!("cmd finished") });
                    thread::sleep(Duration::from_secs_f64(interval_clone));
                }
            });
        }
    }

    // Prepare ping data vec
    let mut datas: Vec<PingData> = hosts_info.into_iter().map(|hi| PingData::new(hi)).collect();

    // For colors, we need to map colors to ratatui colors
    // Parse all_color_pieces into ratatui colors for valid ones
    fn parse_color_to_ratatui(s: &str) -> ratatui::style::Color {
        let trimmed = s.trim();
        if trimmed.starts_with('#') && trimmed.len() == 7 {
            // hex
            if let Ok(r) = u8::from_str_radix(&trimmed[1..3], 16) {
                if let Ok(g) = u8::from_str_radix(&trimmed[3..5], 16) {
                    if let Ok(b) = u8::from_str_radix(&trimmed[5..7], 16) {
                        return ratatui::style::Color::Rgb(r,g,b);
                    }
                }
            }
        }
        let lower = trimmed.to_lowercase();
        match lower.as_str() {
            "black" => ratatui::style::Color::Black,
            "red" => ratatui::style::Color::Red,
            "green" => ratatui::style::Color::Green,
            "yellow" => ratatui::style::Color::Yellow,
            "blue" => ratatui::style::Color::Blue,
            "magenta" => ratatui::style::Color::Magenta,
            "cyan" => ratatui::style::Color::Cyan,
            "gray" => ratatui::style::Color::Gray,
            "dark-gray" => ratatui::style::Color::DarkGray,
            "light-red" => ratatui::style::Color::LightRed,
            "light-green" => ratatui::style::Color::LightGreen,
            "light-yellow" => ratatui::style::Color::LightYellow,
            "light-blue" => ratatui::style::Color::LightBlue,
            "light-magenta" => ratatui::style::Color::LightMagenta,
            "light-cyan" => ratatui::style::Color::LightCyan,
            "white" => ratatui::style::Color::White,
            _ => ratatui::style::Color::White,
        }
    }

    let mut color_map: Vec<ratatui::style::Color> = Vec::new();
    for piece in &all_color_pieces {
        if is_valid(piece) {
            color_map.push(parse_color_to_ratatui(piece));
        } else {
            // invalid but beyond needed? We already handled validation for needed, but for extra beyond needed, we ignore invalid? For color_map, we should only include valid ones up to hosts len? Actually we want to assign colors in order of valid colors.
            // For simplicity, if piece is invalid but beyond hosts len, skip.
            // If invalid within needed, we already errored.
            // So for valid case, all pieces within needed are valid.
            if color_map.len() < datas.len() {
                // This piece is invalid but should have been errored earlier, so we won't reach here.
                // But for extra beyond hosts, we ignore.
            }
        }
    }
    // If we have fewer colors than hosts, fill with default colors (some cycle)
    let default_colors = vec![
        ratatui::style::Color::Red,
        ratatui::style::Color::Green,
        ratatui::style::Color::Yellow,
        ratatui::style::Color::Blue,
        ratatui::style::Color::Magenta,
        ratatui::style::Color::Cyan,
    ];
    while color_map.len() < datas.len() {
        color_map.push(default_colors[color_map.len() % default_colors.len()]);
    }

    // Main loop
    let mut should_quit = false;
    while !should_quit {
        // Poll events
        while let Ok(event) = rx.try_recv() {
            match event {
                PingEvent::Data { host_idx, duration, line: _ } => {
                    if host_idx < datas.len() {
                        datas[host_idx].add(duration);
                    }
                }
                PingEvent::Error { host_idx: _, error } => {
                    // Restore terminal and print error
                    let _ = disable_raw_mode();
                    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
                    eprintln!("{}", error);
                    process::exit(1);
                }
            }
        }

        // Clean old data based on buffer
        let now = Instant::now();
        let buffer_dur = Duration::from_secs(buffer);
        for data in &mut datas {
            while let Some((t, _)) = data.times.front() {
                if now.duration_since(*t) > buffer_dur {
                    data.times.pop_front();
                } else {
                    break;
                }
            }
        }

        // Draw
        let _ = terminal.draw(|f| {
            let size = f.area();
            // Apply margins
            let v_margin = vertical_margin as u16;
            let h_margin = horizontal_margin as u16;
            let inner = ratatui::layout::Rect {
                x: size.x + h_margin,
                y: size.y + v_margin,
                width: size.width.saturating_sub(h_margin*2),
                height: size.height.saturating_sub(v_margin*2),
            };

            // Layout: vertical for each host header + graph area
            // For each host, we have a header line, then graph. But original shows all hosts' headers at top, then single graph area with multiple lines?
            // Actually from captures, headers are stacked: each host has its own header line, then below is the graph.
            // Example with 2 hosts: 
            // google.com ...
            // 8.8.8.8 ...
            // graph
            // So we need to render headers first.

            let mut constraints = Vec::new();
            for _ in &datas {
                constraints.push(ratatui::layout::Constraint::Length(1));
            }
            constraints.push(ratatui::layout::Constraint::Min(0));

            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints(constraints)
                .split(inner);

            for (i, data) in datas.iter().enumerate() {
                let header = {
                    let last_str = data.last.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                    let min_str = data.min.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                    let max_str = data.max.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                    let avg_str = data.avg().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                    let jtr_str = data.jitter().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                    // p95: calculate 95th percentile from times
                    let mut durations: Vec<Duration> = data.times.iter().filter_map(|(_, d)| *d).collect();
                    durations.sort();
                    let p95_str = if durations.is_empty() {
                        "0ns".to_string()
                    } else {
                        let idx = ((durations.len() as f64) * 0.95).ceil() as usize -1;
                        let idx = idx.min(durations.len()-1);
                        format_duration(durations[idx])
                    };
                    format!("{} ({})               last {}  min {}  max {}  avg {}  jtr {}  p95 {}  t/o {}",
                        data.host_info.display,
                        data.host_info.resolved_ip,
                        last_str,
                        min_str,
                        max_str,
                        avg_str,
                        jtr_str,
                        p95_str,
                        data.timeouts
                    )
                };
                let paragraph = Paragraph::new(header)
                    .style(Style::default().fg(color_map.get(i).cloned().unwrap_or(Color::White)));
                f.render_widget(paragraph, chunks[i]);
            }

            // Graph area is last chunk
            let graph_area = chunks.last().cloned().unwrap_or(inner);
            // For graph, we need to render y-axis labels and braille.

            // Simplified: we will render a placeholder with tui Chart? Let's do simple braille rendering manually.

            // Collect all durations for y scaling
            let mut all_vals: Vec<f64> = Vec::new();
            for data in &datas {
                for (_, opt) in &data.times {
                    if let Some(d) = opt {
                        all_vals.push(d.as_secs_f64()*1000.0); // ms
                    }
                }
            }
            let (y_min, y_max) = if all_vals.is_empty() {
                (0.0, 1.0)
            } else {
                let min = all_vals.iter().cloned().fold(f64::INFINITY, f64::min);
                let max = all_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
                if (max - min).abs() < 0.01 {
                    ( (min*0.9).max(0.0), max*1.1 )
                } else {
                    ( (min*0.9).max(0.0), max*1.1 )
                }
            };

            // For x axis: time from now - buffer to now
            // We need to render braille dots
            // We'll use a simple approach: create a canvas of height = graph_area.height -1 (for x labels) and width = graph_area.width - 8 (for y labels)
            // Then for each data point, map its time to x, and its value to y.

