#[derive(Debug, Clone)]
struct HostInfo {
    original: String,
    mapped: String,
    resolved_ip: String,
    is_ipv6_literal: bool,
}

fn map_cloud(host: &str) -> String {
    if let Some(region) = host.strip_prefix("aws:") {
        format!("ec2.{}.amazonaws.com", region)
    } else if let Some(region) = host.strip_prefix("gcp:") {
        format!("storage.{}.rep.googleapis.com", region)
    } else {
        host.to_string()
    }
}

fn resolve_host(host: &str, four: bool, six: bool) -> Result<Vec<IpAddr>, String> {
    if let Ok(ip) = IpAddr::from_str(host) {
        if four && !ip.is_ipv4() {
            return Err(format!("Error: Could not resolve '{}' to IPv4", host));
        }
        if six && !ip.is_ipv6() {
            return Err(format!("Error: Could not resolve '{}' to IPv6", host));
        }
        return Ok(vec![ip]);
    }
    let addrs = (host, 0).to_socket_addrs();
    match addrs {
        Ok(iter) => {
            let ips: Vec<IpAddr> = iter.map(|sa| sa.ip()).collect();
            if four {
                let v4: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv4()).cloned().collect();
                if v4.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv4", host));
                }
                Ok(v4)
            } else if six {
                let v6: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv6()).cloned().collect();
                if v6.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv6", host));
                }
                Ok(v6)
            } else {
                if ips.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv4", host));
                }
                Ok(ips)
            }
        }
        Err(e) => {
            Err(format!("Error: Resolving {}\n\nCaused by:\n    {}", host, e))
        }
    }
}

fn check_ping_binary() -> Result<(), String> {
    let output = std::process::Command::new("ping").arg("-V").output();
    match output {
        Ok(out) => {
            let stdout = String::from_utf8_lossy(&out.stdout);
            let stderr = String::from_utf8_lossy(&out.stderr);
            let combined = format!("{} {}", stdout, stderr).to_lowercase();
            if combined.contains("inetutils") {
                return Err("Error: Installed ping is not supported: Please use iputils ping, not inetutils.".to_string());
            }
            if combined.contains("iputils") {
                return Ok(());
            }
            let stdout_str = stdout.trim().to_string();
            let stderr_str = stderr.trim().to_string();
            let stdout_vec: Vec<String> = if stdout_str.is_empty() { vec![] } else { vec![stdout_str] };
            let stderr_vec: Vec<String> = if stderr_str.is_empty() { vec![] } else { vec![stderr_str] };
            return Err(format!("Error: Could not detect ping. Stderr: {:?}\nStdout: {:?}", stderr_vec, stdout_vec));
        }
        Err(e) => {
            return Err(format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e, e.raw_os_error().unwrap_or(2), e, e.raw_os_error().unwrap_or(2)));
        }
    }
}

fn format_duration(d: Duration) -> String {
    let secs = d.as_secs_f64();
    if secs >= 1.0 {
        if secs >= 10.0 {
            format!("{:.0}s", secs)
        } else {
            format!("{:.1}s", secs)
        }
    } else {
        let ms = secs * 1000.0;
        if ms >= 1.0 {
            if ms >= 100.0 {
                format!("{:.0}ms", ms)
            } else {
                format!("{:.1}ms", ms)
            }
        } else {
            let us = secs * 1_000_000.0;
            if us >= 10.0 {
                format!("{:.0}µs", us)
            } else {
                format!("{:.1}µs", us)
            }
        }
    }
}

