    let ping_args: Vec<String> = matches.get_many::<String>("ping-args").map(|v| v.cloned().collect()).unwrap_or_default();
    let hosts_raw: Vec<String> = matches.get_many::<String>("hosts").map(|v| v.cloned().collect()).unwrap_or_default();

    if hosts_raw.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
