cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command};
use std::process;
use std::net::{ToSocketAddrs, IpAddr};
use std::str::FromStr;
use std::time::{Duration, Instant};
use regex::Regex;
use std::collections::VecDeque;

fn build_cli() -> Command {
    Command::new("gping")
        .version("1.20.1")
        .long_version("1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-08-10 23:10:43 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
        .about("Ping, but with a graph.")
        .arg(Arg::new("cmd").long("cmd").action(ArgAction::SetTrue).help("Graph the execution time for a list of commands rather than pinging hosts"))
        .arg(Arg::new("watch-interval").short('n').long("watch-interval").value_name("WATCH_INTERVAL").value_parser(clap::value_parser!(f64)).help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5"))
        .arg(Arg::new("buffer").short('b').long("buffer").value_name("BUFFER").default_value("30").value_parser(clap::value_parser!(u64)).help("Determines the number of seconds to display in the graph"))
        .arg(Arg::new("4").short('4').action(ArgAction::SetTrue).help("Resolve ping targets to IPv4 address").conflicts_with("6"))
        .arg(Arg::new("6").short('6').action(ArgAction::SetTrue).help("Resolve ping targets to IPv6 address"))
        .arg(Arg::new("interface").short('i').long("interface").value_name("INTERFACE").help("Interface to use when pinging"))
        .arg(Arg::new("simple-graphics").short('s').long("simple-graphics").action(ArgAction::SetTrue).help(""))
        .arg(Arg::new("vertical-margin").long("vertical-margin").value_name("VERTICAL_MARGIN").default_value("1").value_parser(clap::value_parser!(u64)).help("Vertical margin around the graph (top and bottom)"))
        .arg(Arg::new("horizontal-margin").long("horizontal-margin").value_name("HORIZONTAL_MARGIN").default_value("0").value_parser(clap::value_parser!(u64)).help("Horizontal margin around the graph (left and right)"))
        .arg(Arg::new("color").short('c').long("color").value_name("color").action(ArgAction::Append).help("Assign color to a graph entry.\n\nThis option can be defined more than once as a comma separated string, and the\norder which the colors are provided will be matched against the hosts or\ncommands passed to gping.\n\nHexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the\nfollowing color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',\n'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',\n'light-blue', 'light-magenta', 'light-cyan', and 'white'"))
        .arg(Arg::new("clear").long("clear").action(ArgAction::SetTrue).help("Clear the graph from the terminal after closing the program"))
        .arg(Arg::new("ping-args").long("ping-args").value_name("PING_ARGS").num_args(0..).allow_hyphen_values(true).help("Extra arguments to pass to `ping`. These are platform dependent"))
        .arg(Arg::new("hosts").value_name("HOSTS_OR_COMMANDS").num_args(0..).help("Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1"))
}

#[derive(Debug, Clone)]
struct HostInfo {
    original: String,
    mapped: String,
    resolved_ip: String,
    is_ipv6_literal: bool,
}

fn map_cloud(host: &str) -> String {
    if let Some(region) = host.strip_prefix("aws:") {
        format!("ec2.{}.amazonaws.com", region)
    } else if let Some(region) = host.strip_prefix("gcp:") {
        format!("storage.{}.rep.googleapis.com", region)
    } else {
        host.to_string()
    }
}

fn resolve_host(host: &str, four: bool, six: bool) -> Result<Vec<IpAddr>, String> {
    if let Ok(ip) = IpAddr::from_str(host) {
        if four && !ip.is_ipv4() {
            return Err(format!("Error: Could not resolve '{}' to IPv4", host));
        }
        if six && !ip.is_ipv6() {
            return Err(format!("Error: Could not resolve '{}' to IPv6", host));
        }
        return Ok(vec![ip]);
    }
    let addrs = (host, 0).to_socket_addrs();
    match addrs {
        Ok(iter) => {
            let ips: Vec<IpAddr> = iter.map(|sa| sa.ip()).collect();
            if four {
                let v4: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv4()).cloned().collect();
                if v4.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv4", host));
                }
                Ok(v4)
            } else if six {
                let v6: Vec<IpAddr> = ips.iter().filter(|ip| ip.is_ipv6()).cloned().collect();
                if v6.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv6", host));
                }
                Ok(v6)
            } else {
                if ips.is_empty() {
                    return Err(format!("Error: Could not resolve '{}' to IPv4", host));
                }
                Ok(ips)
            }
        }
        Err(e) => {
            Err(format!("Error: Resolving {}\n\nCaused by:\n    {}", host, e))
        }
    }
}

fn check_ping_binary() -> Result<(), String> {
    let output = std::process::Command::new("ping").arg("-V").output();
    match output {
        Ok(out) => {
            let stdout = String::from_utf8_lossy(&out.stdout);
            let stderr = String::from_utf8_lossy(&out.stderr);
            let combined = format!("{} {}", stdout, stderr).to_lowercase();
            if combined.contains("inetutils") {
                return Err("Error: Installed ping is not supported: Please use iputils ping, not inetutils.".to_string());
            }
            if combined.contains("iputils") {
                return Ok(());
            }
            let stdout_str = stdout.trim().to_string();
            let stderr_str = stderr.trim().to_string();
            let stdout_vec: Vec<String> = if stdout_str.is_empty() { vec![] } else { vec![stdout_str] };
            let stderr_vec: Vec<String> = if stderr_str.is_empty() { vec![] } else { vec![stderr_str] };
            return Err(format!("Error: Could not detect ping. Stderr: {:?}\nStdout: {:?}", stderr_vec, stdout_vec));
        }
        Err(e) => {
            return Err(format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e, e.raw_os_error().unwrap_or(2), e, e.raw_os_error().unwrap_or(2)));
        }
    }
}

fn format_duration(d: Duration) -> String {
    let secs = d.as_secs_f64();
    if secs >= 1.0 {
        if secs >= 10.0 {
            format!("{:.0}s", secs)
        } else {
            format!("{:.1}s", secs)
        }
    } else {
        let ms = secs * 1000.0;
        if ms >= 1.0 {
            if ms >= 100.0 {
                format!("{:.0}ms", ms)
            } else {
                format!("{:.1}ms", ms)
            }
        } else {
            let us = secs * 1_000_000.0;
            if us >= 10.0 {
                format!("{:.0}µs", us)
            } else {
                format!("{:.1}µs", us)
            }
        }
    }
}

fn main() {
    let cli = build_cli();
    let matches = cli.get_matches();

    let is_cmd = matches.get_flag("cmd");
    let watch_interval_opt: Option<f64> = matches.get_one::<f64>("watch-interval").cloned();
    let buffer: u64 = *matches.get_one::<u64>("buffer").unwrap();
    let four = matches.get_flag("4");
    let six = matches.get_flag("6");
    let interface: Option<String> = matches.get_one::<String>("interface").cloned();
    let vertical_margin: u64 = *matches.get_one::<u64>("vertical-margin").unwrap();
    let horizontal_margin: u64 = *matches.get_one::<u64>("horizontal-margin").unwrap();
    let clear = matches.get_flag("clear");
    let ping_args: Vec<String> = matches.get_many::<String>("ping-args").map(|v| v.cloned().collect()).unwrap_or_default();
    let hosts_raw: Vec<String> = matches.get_many::<String>("hosts").map(|v| v.cloned().collect()).unwrap_or_default();
    let _simple = matches.get_flag("simple-graphics");

    if hosts_raw.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        process::exit(1);
    }

    let color_raw: Vec<String> = matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut all_color_pieces: Vec<String> = Vec::new();
    for raw in &color_raw {
        for part in raw.split(',') {
            all_color_pieces.push(part.to_string());
        }
    }

    let validate_count = std::cmp::min(all_color_pieces.len(), hosts_raw.len());
    let is_valid = |piece: &str| -> bool {
        if piece.len() == 7 && piece.starts_with('#') && piece[1..].chars().all(|c| c.is_ascii_hexdigit()) {
            return true;
        }
        let trimmed = piece.trim();
        if trimmed.is_empty() {
            return false;
        }
        let lower = trimmed.to_lowercase();
        matches!(lower.as_str(), "black"|"red"|"green"|"yellow"|"blue"|"magenta"|"cyan"|"gray"|"dark-gray"|"light-red"|"light-green"|"light-yellow"|"light-blue"|"light-magenta"|"light-cyan"|"white")
    };

    for i in 0..validate_count {
        let piece = &all_color_pieces[i];
        if !is_valid(piece) {
            eprintln!("Error: Invalid color code: `{}`\n\nCaused by:\n    Failed to parse Colors", piece);
            process::exit(1);
        }
    }

    let mut hosts_info: Vec<HostInfo> = Vec::new();
    if is_cmd {
        for original in &hosts_raw {
            hosts_info.push(HostInfo {
                original: original.clone(),
                mapped: original.clone(),
                resolved_ip: String::new(),
                is_ipv6_literal: false,
            });
        }
    } else {
        for original in &hosts_raw {
            let mapped = map_cloud(original);
            let resolve_result = resolve_host(&mapped, four, six);
            match resolve_result {
                Ok(ips) => {
                    let display_ip = if four {
                        ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                    } else if six {
                        ips.iter().find(|ip| ip.is_ipv6()).cloned().unwrap_or(ips[0])
                    } else {
                        ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                    };
                    let is_v6_lit = {
                        if let Ok(ip) = IpAddr::from_str(original) {
                            ip.is_ipv6()
                        } else if let Ok(ip) = IpAddr::from_str(&mapped) {
                            ip.is_ipv6()
                        } else {
                            original.contains(':') || mapped.contains(':')
                        }
                    };
                    hosts_info.push(HostInfo {
                        original: original.clone(),
                        mapped: mapped.clone(),
                        resolved_ip: display_ip.to_string(),
                        is_ipv6_literal: is_v6_lit,
                    });
                }
                Err(err_msg) => {
                    eprintln!("{}", err_msg);
                    process::exit(1);
                }
            }
        }

        if let Err(e) = check_ping_binary() {
            eprintln!("{}", e);
            process::exit(1);
        }
    }

    let default_interval = if is_cmd { 0.5 } else { 0.2 };
    let interval = watch_interval_opt.unwrap_or(default_interval);
    let interval_str = format!("{:.1}", interval);

    use std::sync::mpsc::{self};
    use std::thread;

    enum PingEvent {
        Data { host_idx: usize, duration: Option<Duration> },
        Error { error: String },
    }

    let (tx, rx) = mpsc::channel();

    if !is_cmd {
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let mapped = host_info.mapped.clone();
            let interval_str_clone = interval_str.clone();
            let interface_clone = interface.clone();
            let ping_args_clone = ping_args.clone();
            let tx_clone = tx.clone();
            let is_ipv6 = if six { true } else if four { false } else { host_info.is_ipv6_literal };
            let ping_bin = if is_ipv6 { "ping6" } else { "ping" };
            thread::spawn(move || {
                let mut args: Vec<String> = vec![];
                args.push("-O".to_string());
                args.push(format!("-i{}", interval_str_clone));
                if let Some(ref iface) = interface_clone {
                    args.push("-I".to_string());
                    args.push(iface.clone());
                }
                for pa in ping_args_clone {
                    args.push(pa);
                }
                args.push(mapped.clone());

                let mut child = match std::process::Command::new(ping_bin)
                    .args(&args)
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::piped())
                    .spawn() {
                        Ok(c) => c,
                        Err(e) => {
                            if ping_bin == "ping6" {
                                match std::process::Command::new("ping")
                                    .args(&args)
                                    .stdout(std::process::Stdio::piped())
                                    .stderr(std::process::Stdio::piped())
                                    .spawn() {
                                        Ok(c) => c,
                                        Err(e2) => {
                                            let _ = tx_clone.send(PingEvent::Error { error: format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e2, e2.raw_os_error().unwrap_or(2), e2, e2.raw_os_error().unwrap_or(2)) });
                                            return;
                                        }
                                    }
                            } else {
                                let _ = tx_clone.send(PingEvent::Error { error: format!("Error: Error spawning ping: {} (os error {})\n\nCaused by:\n    {} (os error {})", e, e.raw_os_error().unwrap_or(2), e, e.raw_os_error().unwrap_or(2)) });
                                return;
                            }
                        }
                    };

                let stdout = child.stdout.take().unwrap();
                let reader = std::io::BufReader::new(stdout);
                use std::io::BufRead;
                let re = Regex::new(r"time=([0-9]+\.?[0-9]*)\s*ms").unwrap();
                let timeout_re = Regex::new(r"no answer yet").unwrap();
                for line in reader.lines() {
                    if let Ok(l) = line {
                        if timeout_re.is_match(&l) {
                            let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: None });
                        } else if let Some(cap) = re.captures(&l) {
                            if let Some(m) = cap.get(1) {
                                if let Ok(ms) = f64::from_str(m.as_str()) {
                                    let dur = Duration::from_secs_f64(ms / 1000.0);
                                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(dur) });
                                }
                            }
                        }
                    }
                }
            });
        }
    } else {
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let cmd_str = host_info.original.clone();
            let tx_clone = tx.clone();
            let interval_clone = interval;
            thread::spawn(move || {
                loop {
                    let start = Instant::now();
                    let _ = std::process::Command::new("sh").arg("-c").arg(&cmd_str).output();
                    let elapsed = start.elapsed();
                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(elapsed) });
                    thread::sleep(Duration::from_secs_f64(interval_clone));
                }
            });
        }
    }

    use crossterm::tty::IsTty;
    if !std::io::stdout().is_tty() {
        thread::sleep(Duration::from_millis(200));
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }

    use crossterm::{
        execute,
        terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
        event::{self, Event, KeyCode},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Layout, Constraint, Direction},
        style::{Color, Style},
        widgets::Paragraph,
        Terminal,
    };

    if enable_raw_mode().is_err() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let mut stdout = std::io::stdout();
    if execute!(stdout, EnterAlternateScreen).is_err() {
        let _ = disable_raw_mode();
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            eprintln!("Error: No such device or address (os error 6)");
            process::exit(1);
        }
    };

    struct PingData {
        host_info: HostInfo,
        times: VecDeque<(Instant, Option<Duration>)>,
        last: Option<Duration>,
        min: Option<Duration>,
        max: Option<Duration>,
        sum: Duration,
        count: u64,
        timeouts: u64,
        jitter_sum: Duration,
        prev: Option<Duration>,
    }

    impl PingData {
        fn new(host_info: HostInfo) -> Self {
            Self {
                host_info,
                times: VecDeque::new(),
                last: None,
                min: None,
                max: None,
                sum: Duration::from_secs(0),
                count: 0,
                timeouts: 0,
                jitter_sum: Duration::from_secs(0),
                prev: None,
            }
        }
        fn add(&mut self, dur: Option<Duration>) {
            let now = Instant::now();
            self.times.push_back((now, dur));
            if let Some(d) = dur {
                self.last = Some(d);
                self.min = Some(match self.min { Some(m) => if d < m { d } else { m }, None => d });
                self.max = Some(match self.max { Some(m) => if d > m { d } else { m }, None => d });
                self.sum += d;
                self.count += 1;
                if let Some(prev) = self.prev {
                    let diff = if d > prev { d - prev } else { prev - d };
                    self.jitter_sum += diff;
                }
                self.prev = Some(d);
            } else {
                self.timeouts += 1;
            }
        }
        fn avg(&self) -> Option<Duration> { if self.count==0 { None } else { Some(self.sum / self.count as u32) } }
        fn jitter(&self) -> Option<Duration> { if self.count<=1 { None } else { Some(self.jitter_sum / (self.count-1) as u32) } }
    }

    let mut datas: Vec<PingData> = hosts_info.into_iter().map(|hi| PingData::new(hi)).collect();

    fn parse_color_to_ratatui(s: &str) -> Color {
        let trimmed = s.trim();
        if trimmed.len()==7 && trimmed.starts_with('#') {
            if let Ok(r) = u8::from_str_radix(&trimmed[1..3], 16) {
                if let Ok(g) = u8::from_str_radix(&trimmed[3..5], 16) {
                    if let Ok(b) = u8::from_str_radix(&trimmed[5..7], 16) {
                        return Color::Rgb(r,g,b);
                    }
                }
            }
        }
        let lower = trimmed.to_lowercase();
        match lower.as_str() {
            "black" => Color::Black,
            "red" => Color::Red,
            "green" => Color::Green,
            "yellow" => Color::Yellow,
            "blue" => Color::Blue,
            "magenta" => Color::Magenta,
            "cyan" => Color::Cyan,
            "gray" => Color::Gray,
            "dark-gray" => Color::DarkGray,
            "light-red" => Color::LightRed,
            "light-green" => Color::LightGreen,
            "light-yellow" => Color::LightYellow,
            "light-blue" => Color::LightBlue,
            "light-magenta" => Color::LightMagenta,
            "light-cyan" => Color::LightCyan,
            "white" => Color::White,
            _ => Color::White,
        }
    }

    let mut color_map: Vec<Color> = Vec::new();
    for piece in &all_color_pieces {
        if is_valid(piece) {
            color_map.push(parse_color_to_ratatui(piece));
        }
    }
    let default_colors = vec![Color::Red, Color::Green, Color::Yellow, Color::Blue, Color::Magenta, Color::Cyan];
    while color_map.len() < datas.len() {
        color_map.push(default_colors[color_map.len() % default_colors.len()]);
    }

    let buffer_dur = Duration::from_secs(buffer);
    let mut should_quit = false;
    while !should_quit {
        while let Ok(event) = rx.try_recv() {
            match event {
                PingEvent::Data { host_idx, duration } => {
                    if host_idx < datas.len() {
                        datas[host_idx].add(duration);
                    }
                }
                PingEvent::Error { error } => {
                    let _ = disable_raw_mode();
                    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
                    eprintln!("{}", error);
                    process::exit(1);
                }
            }
        }
        let now = Instant::now();
        for data in &mut datas {
            while let Some((t,_)) = data.times.front() {
                if now.duration_since(*t) > buffer_dur {
                    data.times.pop_front();
                } else { break; }
            }
        }
        let _ = terminal.draw(|f| {
            let size = f.area();
            let v_margin = vertical_margin as u16;
            let h_margin = horizontal_margin as u16;
            let inner = ratatui::layout::Rect {
                x: size.x + h_margin,
                y: size.y + v_margin,
                width: size.width.saturating_sub(h_margin*2),
                height: size.height.saturating_sub(v_margin*2),
            };
            let mut constraints = Vec::new();
            for _ in &datas { constraints.push(Constraint::Length(1)); }
            constraints.push(Constraint::Min(0));
            let chunks = Layout::default().direction(Direction::Vertical).constraints(constraints).split(inner);
            for (i, data) in datas.iter().enumerate() {
                let last_str = data.last.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let min_str = data.min.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let max_str = data.max.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let avg_str = data.avg().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let jtr_str = data.jitter().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let mut durations: Vec<Duration> = data.times.iter().filter_map(|(_, d)| *d).collect();
                durations.sort();
                let p95_str = if durations.is_empty() { "0ns".to_string() } else {
                    let idx = ((durations.len() as f64)*0.95).ceil() as usize -1;
                    let idx = idx.min(durations.len()-1);
                    format_duration(durations[idx])
                };
                let display_name = if is_cmd {
                    data.host_info.original.clone()
                } else {
                    format!("{} ({})", data.host_info.original, data.host_info.resolved_ip)
                };
                let header = format!("{:<50} last {:<8} min {:<8} max {:<8} avg {:<8} jtr {:<8} p95 {:<8} t/o {}", display_name, last_str, min_str, max_str, avg_str, jtr_str, p95_str, data.timeouts);
                let para = Paragraph::new(header).style(Style::default().fg(color_map.get(i).cloned().unwrap_or(Color::White)));
                f.render_widget(para, chunks[i]);
            }
            let graph_area = chunks.last().cloned().unwrap_or(inner);
            let graph_height = graph_area.height.saturating_sub(1) as usize;
            let graph_width = graph_area.width.saturating_sub(10) as usize;
            let mut all_vals: Vec<f64> = Vec::new();
            for data in &datas {
                for (_, opt) in &data.times {
                    if let Some(d) = opt { all_vals.push(d.as_secs_f64()*1000.0); }
                }
            }
            let (y_min, y_max) = if all_vals.is_empty() { (0.0, 1.0) } else {
                let min = all_vals.iter().cloned().fold(f64::INFINITY, f64::min);
                let max = all_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
                if (max-min).abs() < 0.01 { ((min*0.9).max(0.0), max*1.1) } else { ((min*0.9).max(0.0), max*1.1) }
            };
            let mut lines = Vec::new();
            for i in 0..graph_height {
                let y_val = y_max - (i as f64 / graph_height as f64)*(y_max - y_min);
                lines.push(format!("{:>6.0}ms │", y_val));
            }
            lines.push(format!("       └{}", "─".repeat(graph_width)));
            let text = lines.join("\n");
            let gp = Paragraph::new(text);
            f.render_widget(gp, graph_area);
        });
        if event::poll(Duration::from_millis(100)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || (key.code == KeyCode::Char('c') && key.modifiers.contains(event::KeyModifiers::CONTROL)) {
                    should_quit = true;
                }
            }
        }
    }
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    if clear {
        let _ = execute!(std::io::stdout(), crossterm::terminal::Clear(crossterm::terminal::ClearType::All));
    }
}
