                // Braille unicode: U+2800 + dots pattern
                // Dot mapping for braille: positions:
                // dot 1: (0,0), dot2: (0,1), dot3: (0,2), dot4: (1,0), dot5: (1,1), dot6: (1,2), dot7: (0,3), dot8: (1,3)
                // Actually standard: 
                //   col 0: dots 1,2,3,7
                //   col 1: dots 4,5,6,8
                // Row mapping: y within char 0..3

                for char_row in 0..braille_height {
                    let y_val = y_max - (char_row as f64 / braille_height as f64)*(y_max - y_min);
                    let mut line = format!("{:>6.0}ms │", y_val);
                    for char_col in 0..braille_width {
                        let mut bits = 0u8;
                        // Check 8 dots
                        for dot_y in 0..4 {
                            for dot_x in 0..2 {
                                let global_y = char_row*4 + dot_y;
                                let global_x = char_col*2 + dot_x;
                                if global_y < dot_height && global_x < dot_width {
                                    if dot_grid[global_y][global_x].is_some() {
                                        let dot_num = match (dot_x, dot_y) {
                                            (0,0) => 0, // dot1
                                            (0,1) => 1, // dot2
                                            (0,2) => 2, // dot3
                                            (1,0) => 3, // dot4
                                            (1,1) => 4, // dot5
                                            (1,2) => 5, // dot6
                                            (0,3) => 6, // dot7
                                            (1,3) => 7, // dot8
                                            _ => 0,
