                                }
                            }
                        }
                        if bits == 0 {
                            line.push(' ');
                        } else {
                            let ch = std::char::from_u32(0x2800 + bits as u32).unwrap_or(' ');
                            line.push(ch);
                        }
                    }
                    lines.push(line);
                }
            }

            // X axis
            // Generate time labels: from now-buffer to now
            // Original shows time like "16:07:45"
            // We'll show start, middle, end times
            let x_axis = format!("       └{}", "─".repeat(plot_width));
            lines.push(x_axis);

            // For time labels below x axis, we could add a line with timestamps, but our graph area height includes only graph + x axis, no extra line for timestamps.
