    let simple_graphics = matches.get_flag("simple-graphics");

    if hosts_raw.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        process::exit(1);
    }

    let color_raw: Vec<String> = matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut all_color_pieces: Vec<String> = Vec::new();
    for raw in &color_raw {
        for part in raw.split(',') {
            all_color_pieces.push(part.to_string());
        }
    }

    let validate_count = std::cmp::min(all_color_pieces.len(), hosts_raw.len());
    let is_valid = |piece: &str| -> bool {
        if piece.len() == 7 && piece.starts_with('#') && piece[1..].chars().all(|c| c.is_ascii_hexdigit()) {
            return true;
        }
        let trimmed = piece.trim();
        if trimmed.is_empty() {
            return false;
        }
        let lower = trimmed.to_lowercase();
        matches!(lower.as_str(), "black"|"red"|"green"|"yellow"|"blue"|"magenta"|"cyan"|"gray"|"dark-gray"|"light-red"|"light-green"|"light-yellow"|"light-blue"|"light-magenta"|"light-cyan"|"white")
    };

    for i in 0..validate_count {
        let piece = &all_color_pieces[i];
        if !is_valid(piece) {
            eprintln!("Error: Invalid color code: `{}`\n\nCaused by:\n    Failed to parse Colors", piece);
            process::exit(1);
        }
    }

    let mut hosts_info: Vec<HostInfo> = Vec::new();
    if is_cmd {
        for original in &hosts_raw {
            hosts_info.push(HostInfo {
                original: original.clone(),
                mapped: original.clone(),
                resolved_ip: String::new(),
                is_ipv6_literal: false,
            });
        }
    } else {
        for original in &hosts_raw {
            let mapped = map_cloud(original);
            let resolve_result = resolve_host(&mapped, four, six);
            match resolve_result {
                Ok(ips) => {
                    let display_ip = if four {
                        ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                    } else if six {
                        ips.iter().find(|ip| ip.is_ipv6()).cloned().unwrap_or(ips[0])
                    } else {
                        ips.iter().find(|ip| ip.is_ipv4()).cloned().unwrap_or(ips[0])
                    };
                    let is_v6_lit = {
                        if let Ok(ip) = IpAddr::from_str(original) {
                            ip.is_ipv6()
                        } else if let Ok(ip) = IpAddr::from_str(&mapped) {
                            ip.is_ipv6()
                        } else {
                            original.contains(':') || mapped.contains(':')
                        }
                    };
                    hosts_info.push(HostInfo {
                        original: original.clone(),
                        mapped: mapped.clone(),
                        resolved_ip: display_ip.to_string(),
                        is_ipv6_literal: is_v6_lit,
                    });
                }
                Err(err_msg) => {
                    eprintln!("{}", err_msg);
                    process::exit(1);
                }
            }
        }

        if let Err(e) = check_ping_binary() {
            eprintln!("{}", e);
            process::exit(1);
        }
    }

    let default_interval = if is_cmd { 0.5 } else { 0.2 };
    let interval = watch_interval_opt.unwrap_or(default_interval);
    let interval_str = format!("{:.1}", interval);

    use std::sync::mpsc::{self};
    use std::thread;

    enum PingEvent {
        Data { host_idx: usize, duration: Option<Duration> },
        Error { error: String },
    }

    let (tx, rx) = mpsc::channel();

    if !is_cmd {
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let mapped = host_info.mapped.clone();
            let interval_str_clone = interval_str.clone();
            let interface_clone = interface.clone();
            let ping_args_clone = ping_args.clone();
            let tx_clone = tx.clone();
            let is_ipv6 = if six { true } else if four { false } else { host_info.is_ipv6_literal };
            let ping_bin = if is_ipv6 { "ping6" } else { "ping" };
            thread::spawn(move || {
                let mut args: Vec<String> = vec![];
                args.push("-O".to_string());
                args.push(format!("-i{}", interval_str_clone));
                if let Some(ref iface) = interface_clone {
                    args.push("-I".to_string());
                    args.push(iface.clone());
                }
                for pa in ping_args_clone {
                    args.push(pa);
                }
                args.push(mapped.clone());

                let mut child = match std::process::Command::new(ping_bin)
                    .args(&args)
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::piped())
                    .spawn() {
                        Ok(c) => c,
                        Err(e) => {
                            if ping_bin == "ping6" {
                                match std::process::Command::new("ping")
                                    .args(&args)
                                    .stdout(std::process::Stdio::piped())
                                    .stderr(std::process::Stdio::piped())
                                    .spawn() {
                                        Ok(c) => c,
                                        Err(e2) => {
                                            let _ = tx_clone.send(PingEvent::Error { error: format!("Error: Error spawning ping: {}\n\nCaused by:\n    {}", e2, e2) });
                                            return;
                                        }
                                    }
                            } else {
                                let _ = tx_clone.send(PingEvent::Error { error: format!("Error: Error spawning ping: {}\n\nCaused by:\n    {}", e, e) });
                                return;
                            }
                        }
                    };

                let stdout = child.stdout.take().unwrap();
                let reader = std::io::BufReader::new(stdout);
                use std::io::BufRead;
                let re = Regex::new(r"time=([0-9]+\.?[0-9]*)\s*ms").unwrap();
                let timeout_re = Regex::new(r"no answer yet").unwrap();
                for line in reader.lines() {
                    if let Ok(l) = line {
                        if timeout_re.is_match(&l) {
                            let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: None });
                        } else if let Some(cap) = re.captures(&l) {
                            if let Some(m) = cap.get(1) {
                                if let Ok(ms) = f64::from_str(m.as_str()) {
                                    let dur = Duration::from_secs_f64(ms / 1000.0);
                                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(dur) });
                                }
                            }
                        }
                    }
                }
            });
        }
    } else {
        for (idx, host_info) in hosts_info.iter().enumerate() {
            let cmd_str = host_info.original.clone();
            let tx_clone = tx.clone();
            let interval_clone = interval;
            thread::spawn(move || {
                loop {
                    let start = Instant::now();
                    let _ = std::process::Command::new("sh").arg("-c").arg(&cmd_str).output();
                    let elapsed = start.elapsed();
                    let _ = tx_clone.send(PingEvent::Data { host_idx: idx, duration: Some(elapsed) });
                    thread::sleep(Duration::from_secs_f64(interval_clone));
                }
            });
        }
    }

    use crossterm::tty::IsTty;
    if !std::io::stdout().is_tty() {
        thread::sleep(Duration::from_millis(200));
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }

    use crossterm::{
        execute,
        terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
        event::{self, Event, KeyCode},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Layout, Constraint, Direction},
        style::{Color, Style},
        widgets::Paragraph,
        Terminal,
    };

    if enable_raw_mode().is_err() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let mut stdout = std::io::stdout();
    if execute!(stdout, EnterAlternateScreen).is_err() {
        let _ = disable_raw_mode();
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            eprintln!("Error: No such device or address (os error 6)");
            process::exit(1);
        }
    };

    struct PingData {
        host_info: HostInfo,
        times: VecDeque<(Instant, Option<Duration>)>,
        last: Option<Duration>,
        min: Option<Duration>,
        max: Option<Duration>,
        sum: Duration,
        count: u64,
        timeouts: u64,
        jitter_sum: Duration,
        prev: Option<Duration>,
    }

    impl PingData {
        fn new(host_info: HostInfo) -> Self {
            Self {
                host_info,
                times: VecDeque::new(),
                last: None,
                min: None,
                max: None,
                sum: Duration::from_secs(0),
                count: 0,
                timeouts: 0,
                jitter_sum: Duration::from_secs(0),
                prev: None,
            }
        }
        fn add(&mut self, dur: Option<Duration>) {
            let now = Instant::now();
            self.times.push_back((now, dur));
            if let Some(d) = dur {
                self.last = Some(d);
                self.min = Some(match self.min { Some(m) => if d < m { d } else { m }, None => d });
                self.max = Some(match self.max { Some(m) => if d > m { d } else { m }, None => d });
                self.sum += d;
                self.count += 1;
                if let Some(prev) = self.prev {
                    let diff = if d > prev { d - prev } else { prev - d };
                    self.jitter_sum += diff;
                }
                self.prev = Some(d);
            } else {
                self.timeouts += 1;
            }
        }
        fn avg(&self) -> Option<Duration> { if self.count==0 { None } else { Some(self.sum / self.count as u32) } }
        fn jitter(&self) -> Option<Duration> { if self.count<=1 { None } else { Some(self.jitter_sum / (self.count-1) as u32) } }
    }

    let mut datas: Vec<PingData> = hosts_info.into_iter().map(|hi| PingData::new(hi)).collect();

    fn parse_color_to_ratatui(s: &str) -> Color {
        let trimmed = s.trim();
        if trimmed.len()==7 && trimmed.starts_with('#') {
            if let Ok(r) = u8::from_str_radix(&trimmed[1..3], 16) {
                if let Ok(g) = u8::from_str_radix(&trimmed[3..5], 16) {
                    if let Ok(b) = u8::from_str_radix(&trimmed[5..7], 16) {
                        return Color::Rgb(r,g,b);
                    }
                }
            }
        }
        let lower = trimmed.to_lowercase();
        match lower.as_str() {
            "black" => Color::Black,
            "red" => Color::Red,
            "green" => Color::Green,
            "yellow" => Color::Yellow,
            "blue" => Color::Blue,
            "magenta" => Color::Magenta,
            "cyan" => Color::Cyan,
            "gray" => Color::Gray,
            "dark-gray" => Color::DarkGray,
            "light-red" => Color::LightRed,
            "light-green" => Color::LightGreen,
            "light-yellow" => Color::LightYellow,
            "light-blue" => Color::LightBlue,
            "light-magenta" => Color::LightMagenta,
            "light-cyan" => Color::LightCyan,
            "white" => Color::White,
            _ => Color::White,
        }
    }

    let mut color_map: Vec<Color> = Vec::new();
    for piece in &all_color_pieces {
        if is_valid(piece) {
            color_map.push(parse_color_to_ratatui(piece));
        }
    }
    let default_colors = vec![Color::Red, Color::Green, Color::Yellow, Color::Blue, Color::Magenta, Color::Cyan];
    while color_map.len() < datas.len() {
        color_map.push(default_colors[color_map.len() % default_colors.len()]);
    }

    let buffer_dur = Duration::from_secs(buffer);

    let mut should_quit = false;
    while !should_quit {
        while let Ok(event) = rx.try_recv() {
            match event {
                PingEvent::Data { host_idx, duration } => {
                    if host_idx < datas.len() {
                        datas[host_idx].add(duration);
                    }
                }
                PingEvent::Error { error } => {
                    let _ = disable_raw_mode();
                    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
                    eprintln!("{}", error);
                    process::exit(1);
                }
            }
        }
        let now = Instant::now();
        for data in &mut datas {
            while let Some((t,_)) = data.times.front() {
                if now.duration_since(*t) > buffer_dur {
                    data.times.pop_front();
                } else { break; }
            }
        }
        let _ = terminal.draw(|f| {
            let size = f.area();
            let v_margin = vertical_margin as u16;
            let h_margin = horizontal_margin as u16;
            let inner = ratatui::layout::Rect {
                x: size.x + h_margin,
                y: size.y + v_margin,
                width: size.width.saturating_sub(h_margin*2),
                height: size.height.saturating_sub(v_margin*2),
            };
            let mut constraints = Vec::new();
            for _ in &datas { constraints.push(Constraint::Length(1)); }
            constraints.push(Constraint::Min(0));
            let chunks = Layout::default().direction(Direction::Vertical).constraints(constraints).split(inner);
            for (i, data) in datas.iter().enumerate() {
                let last_str = data.last.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let min_str = data.min.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let max_str = data.max.map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let avg_str = data.avg().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let jtr_str = data.jitter().map(|d| format_duration(d)).unwrap_or("0ns".to_string());
                let mut durations: Vec<Duration> = data.times.iter().filter_map(|(_, d)| *d).collect();
                durations.sort();
                let p95_str = if durations.is_empty() { "0ns".to_string() } else {
                    let idx = ((durations.len() as f64)*0.95).ceil() as usize -1;
                    let idx = idx.min(durations.len()-1);
                    format_duration(durations[idx])
                };
                let display_name = if is_cmd {
                    data.host_info.original.clone()
                } else {
                    format!("{} ({})", data.host_info.original, data.host_info.resolved_ip)
                };
                let header = format!("{:<45} last {:>8}  min {:>8}  max {:>8}  avg {:>8}  jtr {:>8}  p95 {:>8}  t/o {}", display_name, last_str, min_str, max_str, avg_str, jtr_str, p95_str, data.timeouts);
                let para = Paragraph::new(header).style(Style::default().fg(color_map.get(i).cloned().unwrap_or(Color::White)));
                f.render_widget(para, chunks[i]);
            }
            let graph_area = chunks.last().cloned().unwrap_or(inner);
            if graph_area.height < 2 || graph_area.width < 10 {
                return;
            }
            let graph_height = (graph_area.height - 1) as usize;
            let graph_width = graph_area.width as usize;
            let y_label_width = 8;
            let plot_width = graph_width.saturating_sub(y_label_width + 1);
            let plot_height = graph_height;

            let mut all_vals: Vec<f64> = Vec::new();
            for data in &datas {
                for (_, opt) in &data.times {
                    if let Some(d) = opt { all_vals.push(d.as_secs_f64()*1000.0); }
                }
            }
            let (y_min, y_max) = if all_vals.is_empty() { (0.0, 100.0) } else {
                let min = all_vals.iter().cloned().fold(f64::INFINITY, f64::min);
                let max = all_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
                if (max-min).abs() < 0.001 { ((min - 1.0).max(0.0), max + 1.0) } else { ((min - (max-min)*0.1).max(0.0), max + (max-min)*0.1) }
            };

            let dot_width = plot_width * 2;
            let dot_height = plot_height * 4;
            let mut dot_grid: Vec<Vec<Option<Color>>> = vec![vec![None; dot_width]; dot_height];

            for (host_idx, data) in datas.iter().enumerate() {
                let col = color_map.get(host_idx).cloned().unwrap_or(Color::White);
                for (t, opt) in &data.times {
                    if let Some(d) = opt {
                        let elapsed = now.duration_since(*t);
                        if elapsed > buffer_dur { continue; }
                        let x_ratio = 1.0 - (elapsed.as_secs_f64() / buffer_dur.as_secs_f64());
                        let x_dot = (x_ratio * (dot_width as f64 -1.0)) as usize;
                        let ms = d.as_secs_f64()*1000.0;
                        let y_ratio = (ms - y_min) / (y_max - y_min);
                        let y_dot_f = (1.0 - y_ratio) * (dot_height as f64 -1.0);
                        let y_dot = y_dot_f as usize;
                        if y_dot < dot_height && x_dot < dot_width {
                            dot_grid[y_dot][x_dot] = Some(col);
                        }
                    }
                }
            }

            let mut lines: Vec<String> = Vec::new();

            if simple_graphics {
                let mut char_grid: Vec<Vec<char>> = vec![vec![' '; plot_width]; plot_height];
                for y in 0..dot_height {
                    for x in 0..dot_width {
                        if dot_grid[y][x].is_some() {
                            let char_x = x / 2;
                            let char_y = y / 4;
                            if char_y < plot_height && char_x < plot_width {
                                char_grid[char_y][char_x] = '•';
                            }
                        }
                    }
                }
                for row in 0..plot_height {
                    let y_val = y_max - (row as f64 / plot_height as f64)*(y_max - y_min);
                    let mut line = format!("{:>6.0}ms │", y_val);
                    for col in 0..plot_width {
                        line.push(char_grid[row][col]);
                    }
                    lines.push(line);
                }
            } else {
                for char_row in 0..plot_height {
                    let y_val = y_max - (char_row as f64 / plot_height as f64)*(y_max - y_min);
                    let mut line = format!("{:>6.0}ms │", y_val);
                    for char_col in 0..plot_width {
                        let mut bits = 0u8;
                        for dot_y in 0..4 {
                            for dot_x in 0..2 {
                                let global_y = char_row*4 + dot_y;
                                let global_x = char_col*2 + dot_x;
                                if global_y < dot_height && global_x < dot_width {
                                    if dot_grid[global_y][global_x].is_some() {
                                        let dot_num = match (dot_x, dot_y) {
                                            (0,0) => 0,
                                            (0,1) => 1,
                                            (0,2) => 2,
                                            (1,0) => 3,
                                            (1,1) => 4,
                                            (1,2) => 5,
                                            (0,3) => 6,
                                            (1,3) => 7,
                                            _ => 0,
                                        };
                                        bits |= 1 << dot_num;
                                    }
                                }
                            }
                        }
                        if bits == 0 {
                            line.push(' ');
                        } else {
                            let ch = std::char::from_u32(0x2800 + bits as u32).unwrap_or(' ');
                            line.push(ch);
                        }
                    }
                    lines.push(line);
                }
            }

            let x_axis = format!("       └{}", "─".repeat(plot_width));
            lines.push(x_axis);
            let text = lines.join("\n");
            let para = Paragraph::new(text);
            f.render_widget(para, graph_area);
        });
        if event::poll(Duration::from_millis(100)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || (key.code == KeyCode::Char('c') && key.modifiers.contains(event::KeyModifiers::CONTROL)) {
                    should_quit = true;
                }
            }
        }
    }
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    if clear {
        let _ = execute!(std::io::stdout(), crossterm::terminal::Clear(crossterm::terminal::ClearType::All));
    }
}
RS
cargo build --offline --release 2>&1 | tail -n 5
./target/release/gping --version
./target/release/gping -V
./target/release/gping 127.0.0.1 2>&1; echo EXIT:$?
"}

